mapper.select:
select b.id, b.cfg_id, b.oa_sub_id, b.wx_dept_id, b.yx as bind_state, b.remark, b.modedatacreatedate, b.modedatacreatetime, b.modedatamodifydatetime, s.subcompanyname as oa_sub_name, s.supsubcomid as oa_sub_parent, s.canceled as oa_sub_canceled, c.corp_name as cfg_name, c.corp_id as cfg_corp_id, c.root_dept_id as cfg_root_dept_id, c.qy as cfg_sync_enable from ${subBindTable} b left join hrmsubcompany s on s.id = b.oa_sub_id left join ${cfgTable} c on c.id = b.cfg_id
and b.type = 0
and b.cfg_id = #{cfgId}
and b.cfg_id in #{cid}
and (s.subcompanyname like #{keyword} or c.corp_name like #{keyword} or c.corp_id like #{keyword})
order by b.cfg_id, b.oa_sub_id

select id, cfg_id, oa_sub_id, wx_dept_id, yx
from ${table}
where yx = 0 and type = 0 and cfg_id = #{cfgId}
order by oa_sub_id

mapper.update:
update ${table}
set cfg_id = #{e.cfgId},
    yx = #{e.yx},
    remark = #{e.remark},
    modedatamodifier = #{e.modedatamodifier},
    modedatamodifydatetime = #{e.modedatamodifydatetime}
where id = #{e.id}

update ${table}
set wx_dept_id = #{wxDeptId},
    modedatamodifier = #{modifier},
    modedatamodifydatetime = #{now}
where type = 0 and cfg_id = #{cfgId} and oa_sub_id = #{oaSubId}
